import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.CXroN2RO.js";const s="/study/images/game/directstorage.svg",m=JSON.parse('{"title":"DirectStorageでゲームの読み取りと展開をまとめる","description":"","frontmatter":{"title":"DirectStorageでゲームの読み取りと展開をまとめる","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"Windows PCのDirectStorageで読み取りをキューへ積み、バッチの結果を受け取る。GDeflateのCPU・GPU展開、ステージング、描画までの同期を扱う。","aliases":["DirectStorage","GDeflate","BypassIO","IDStorageQueue","EnqueueRequest","EnqueueStatus","EnqueueSignal","GetCompressionSupport","GPU decompression","GPU展開"],"verification":"MicrosoftのWin32 API仕様、DirectStorage SDK資料と公式サンプルに照合（2026-11-06）"}},"headers":[],"relativePath":"game/directstorage.md","filePath":"game/directstorage.md"}'),i={name:"game/directstorage.md"};function n(c,e,d,l,g,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="directstorageでゲームの読み取りと展開をまとめる" tabindex="-1">DirectStorageでゲームの読み取りと展開をまとめる <a class="header-anchor" href="#directstorageでゲームの読み取りと展開をまとめる" aria-label="Permalink to &quot;DirectStorageでゲームの読み取りと展開をまとめる&quot;">​</a></h1><p>オープンワールドで次の地区へ近づくと、地形・建物・テクスチャなど多数のデータが必要になります。Windows PCの<strong>DirectStorage</strong>は、こうした読み取りをまとめて発行し、必要に応じて圧縮データを展開して、システムメモリやDirect3D 12のリソースへ届けるAPIです。たとえば配布用ファイルのどの範囲に各テクスチャがあるかを目次から引き、読み取り要求を組み立てます。何をいつ読み、どこで利用可能とするかはゲーム側で決めます。<a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage-portal" target="_blank" rel="noreferrer">MicrosoftのWin32 DirectStorage概要</a> · <a href="/study/game/asset-loading.html">実行時のアセットロード設計</a></p><figure class="study-figure"><img src="'+s+'" alt="ゲームがファイルの範囲を指定して複数の要求をキューに積み、まとめて提出する。圧縮データはCPUまたはGPUで展開され、指定したメモリやD3D12リソースに届く。ゲームは完了とエラーを確認し、描画用の準備を終えてから利用可能にする。" width="760" height="440" loading="lazy"><figcaption>Windows PCで圧縮アセットを読み取るときの概念図です。展開経路は書き込み先と実行環境によって変わります。<a href="/study/images/game/directstorage.svg" target="_blank" rel="noopener noreferrer">読み取りと展開の図を拡大</a></figcaption></figure><h2 id="要求を積む、提出する、結果を受け取る" tabindex="-1">要求を積む、提出する、結果を受け取る <a class="header-anchor" href="#要求を積む、提出する、結果を受け取る" aria-label="Permalink to &quot;要求を積む、提出する、結果を受け取る&quot;">​</a></h2><ol><li>ファイルを開き、<code>DSTORAGE_REQUEST</code>に読み取り元の範囲、展開形式、書き込み先を指定します。たとえば、パックファイル内のオフセットと圧縮後のサイズを読み取り元に、D3D12バッファの領域を出力先に設定します。圧縮済みなら、展開後のサイズも渡します。<a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/ns-dstorage-dstorage_request" target="_blank" rel="noreferrer">Win32の<code>DSTORAGE_REQUEST</code></a> · <a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/ne-dstorage-dstorage_request_destination_type" target="_blank" rel="noreferrer">書き込み先の種類</a></li><li><code>IDStorageQueue::EnqueueRequest</code>で複数の要求をキューに積みます。グループの末尾に<code>EnqueueStatus</code>でステータスを書き込む項目を積み、<code>Submit</code>で提出します。未提出項目がキュー容量の半分に達した場合は自動提出も行われます。空き枠がない場合は<code>EnqueueRequest</code>が待つため、ゲーム側で発行量を制限し、描画を進めるスレッドに待ちを持ち込まないように設計します。<a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragequeue-enqueuerequest" target="_blank" rel="noreferrer"><code>EnqueueRequest</code></a> · <a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragequeue-submit" target="_blank" rel="noreferrer"><code>Submit</code></a> · <a href="https://github.com/microsoft/DirectStorage/blob/main/Docs/DeveloperGuidance.md#best-practices" target="_blank" rel="noreferrer">Microsoftのバッチ運用ガイド</a></li><li><code>IDStorageStatusArray::GetHResult</code>で、直前のステータス項目から今回の項目までの要求を確認します。<code>E_PENDING</code>は処理中、<code>S_OK</code>はすべて成功、それ以外は失敗した要求のうちキューへの追加順が最初のエラーです。キューのエラーイベントが通知された場合は、<code>RetrieveErrorRecord</code>で診断情報を取得できます。要求をキューに積む時点から処理が終わるまでは、書き込み先など実行に必要な資源を保持します。<a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragequeue-enqueuestatus" target="_blank" rel="noreferrer"><code>EnqueueStatus</code></a> · <a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragestatusarray-gethresult" target="_blank" rel="noreferrer"><code>GetHResult</code></a> · <a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragequeue-retrieveerrorrecord" target="_blank" rel="noreferrer"><code>RetrieveErrorRecord</code></a></li></ol><p><code>EnqueueSignal</code>でD3D12フェンスを積むと、その項目より前の要求が完了した後にフェンス値が更新されます。描画側ではこのフェンスで処理順を合わせ、ステータスで結果を確認します。リソースの状態や依存アセット、エンジンへの登録も揃えたところでゲーム側が利用可能とします。<a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragequeue-enqueuesignal" target="_blank" rel="noreferrer"><code>EnqueueSignal</code></a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization" target="_blank" rel="noreferrer">D3D12キュー間の同期</a> · <a href="/study/graphics/api/directx12.html">Direct3D 12の基礎</a></p><p>読み取り元の位置とサイズをゲーム側がどこから取得するかは、パックの形式で決まります。名前で目次を引き、検証した範囲を使う流れをパックの解説で扱っています。<a href="/study/game/asset-pack-files.html">アセットパックの構成</a></p><p>読み取りや展開の後にD3D12でテクスチャを利用するときは、mipごとの配置、書き込みの完了、シェーダーから読める状態を追います。通常の転送バッファを使う例で、行の配置から完了までを確認できます。<a href="/study/graphics/texture/dds-and-subresources.html">DDSとサブリソース</a> · <a href="/study/graphics/texture/d3d12-texture-upload.html">D3D12のテクスチャ転送</a></p><h2 id="gdeflateで展開する層とテクスチャ形式" tabindex="-1">GDeflateで展開する層とテクスチャ形式 <a class="header-anchor" href="#gdeflateで展開する層とテクスチャ形式" aria-label="Permalink to &quot;GDeflateで展開する層とテクスチャ形式&quot;">​</a></h2><p><strong>GDeflate</strong>は、DirectStorage 1.1で利用できるようになった可逆圧縮形式です。要求の出力先がシステムメモリならCPUが展開します。D3D12リソースへの出力では、対応するGPUとドライバーの経路で展開できます。ドライバー最適化の経路、組み込みのGPUシェーダー、CPUによる代替経路があり、1.2以降の<code>IDStorageQueue2::GetCompressionSupport</code>でキューと圧縮形式に対してランタイムが選んだ経路を調べられます。<a href="https://devblogs.microsoft.com/directx/directstorage-1-1-now-available/" target="_blank" rel="noreferrer">MicrosoftのGDeflateと展開経路の解説</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/dstorage/dstorage/nf-dstorage-idstoragequeue2-getcompressionsupport" target="_blank" rel="noreferrer"><code>GetCompressionSupport</code></a></p><p>たとえば、テクスチャは制作時に<strong>BC7</strong>へ変換し、そのデータを配布時にさらにGDeflateで圧縮できます。読み取り時にGDeflateで展開すると、元のBC7データに戻ります。描画時にはGPUがBC7のブロックからテクスチャの値を読みます。GDeflateはファイル内のデータ量、BC7はテクスチャの保持形式を変える別々の段階です。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/bc7-format" target="_blank" rel="noreferrer">MicrosoftのBC7仕様</a> · <a href="https://github.com/microsoft/DirectStorage/blob/main/Samples/BulkLoadDemo/README.md#building-marc-files" target="_blank" rel="noreferrer">公式BulkLoadDemoのパック作成例</a></p><h2 id="どの経路が使われ、どこで待つかを測る" tabindex="-1">どの経路が使われ、どこで待つかを測る <a class="header-anchor" href="#どの経路が使われ、どこで待つかを測る" aria-label="Permalink to &quot;どの経路が使われ、どこで待つかを測る&quot;">​</a></h2><p>DirectStorageは処理途中のデータを<strong>ステージングバッファ</strong>に置きます。GPU展開の経路では、圧縮データをGPU側へコピーし、コンピュートキューで展開し、結果を目的のリソースへコピーします。出力がステージングを通る場合は、展開後のサイズがそのバッファに収まる必要があります。たとえば複数のmipレベルを別々のタイミングで読むなら、必要な範囲ごとに独立して展開できる形で格納します。バッファを小さくすると空き待ちが増える場合があり、大きくすると描画などに使えるメモリが減ります。バッチの大きさ、発行する要求数、バッファのサイズを一緒に測ります。<a href="https://devblogs.microsoft.com/directx/directstorage-1-1-now-available/" target="_blank" rel="noreferrer">MicrosoftのGPU展開処理</a> · <a href="https://github.com/microsoft/DirectStorage/blob/main/Docs/DeveloperGuidance.md#compressed-assets" target="_blank" rel="noreferrer">データ経路とバッファ設定</a> · <a href="https://github.com/microsoft/DirectStorage/tree/main/Samples/GpuDecompressionBenchmark" target="_blank" rel="noreferrer">公式のGPU展開計測サンプル</a></p><p>Windows 10と11で使えるDirectStorageのリリースがあり、使える機能は採用したSDK、ランタイム、Windowsのバージョン、デバイスとドライバーで決まります。たとえばWindows 11の<strong>BypassIO</strong>は、対応する保存先とドライバーで読み取り経路の一部を短縮します。使えない場合は従来のI/O経路が使われます。GPU展開がCPUへ切り替わる条件は、これとは別に確認します。<a href="https://devblogs.microsoft.com/directx/directstorage-api-downloads/" target="_blank" rel="noreferrer">DirectStorage SDKのリリース一覧</a> · <a href="https://devblogs.microsoft.com/directx/directstorage-1-1-coming-soon/" target="_blank" rel="noreferrer">MicrosoftのWindows対応の説明</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/storage/bypassio" target="_blank" rel="noreferrer">WindowsのBypassIOドライバー仕様</a></p><p>比較では、同じアセットを使い、提出から完了までの時間と、完了から描画できるまでの時間を分けて記録します。CPU時間、GPUのコピー・展開の負荷、描画フレーム時間も合わせると、展開先を変えたときに待ちがどこへ移ったかを確認できます。コードでは<code>HelloDirectStorage</code>がファイルからGPUバッファまでの流れ、<code>BulkLoadDemo</code>がアセットのまとまりと展開経路の比較を扱います。<a href="/study/tools/windows/file-io-tracing.html">ファイルI/Oの観測方法</a> · <a href="https://github.com/microsoft/DirectStorage/tree/main/Samples/HelloDirectStorage" target="_blank" rel="noreferrer">MicrosoftのHelloDirectStorage</a> · <a href="https://github.com/microsoft/DirectStorage/tree/main/Samples/BulkLoadDemo" target="_blank" rel="noreferrer">MicrosoftのBulkLoadDemo</a></p>',15)])])}const h=r(i,[["render",n]]);export{m as __pageData,h as default};
